Lemma deepown_l_persist l v dq :
  deepown_l l v dq ⊢ |==> deepown_l l v DfracDiscarded.
Proof.
  iDestruct 1 as (c) "[Hl Hdeepown]".
  iPersist "Hl". iMod (deepown_persist with "Hdeepown") as "Hdeepown".
  iModIntro. iExists c. by iFrame "∗ #".
Qed.

#[global] Instance deepown_l_persistent l v :
  Persistent (deepown_l l v DfracDiscarded).
Proof. rewrite /deepown_l. apply _. Qed.
End def.

(* Avoid unfolding unrelated large ownership predicates during proof search. *)
#[global] Opaque deepown.
End VolumeSourceV.

Module VolumeV.
Section def.
Context `{hG : !heapGS Σ} `{!ffi_semantics _ _}.
Context {sem : go.Semantics}
  {meta_v1_sem : code.k8s_io.apimachinery.pkg.apis.meta.v1.v1.Assumptions}
  {core_v1_sem : code.k8s_io.api.core.v1.v1.Assumptions}.
Local Set Default Proof Using "All".

Record t := mk {
  Name' : go_string;
  VolumeSource' : VolumeSourceV.t;
}.

#[global] Instance eq_dec : EqDecision t.
Proof using Type. solve_decision. Defined.

Definition deepown (c : api_core_v1.Volume.t) (v : t) dq : iProp Σ :=
  "%Hdeepown_name" ∷ (λ c v (_ : dfrac), ⌜ c = v ⌝)%I c.(api_core_v1.Volume.Name') v.(Name') dq ∗
  "Hdeepown_volumesource" ∷ VolumeSourceV.deepown c.(api_core_v1.Volume.VolumeSource') v.(VolumeSource') dq.

Definition deepown_l l v dq : iProp Σ := ∃ c, l ↦{dq} c ∗ deepown c v dq.

Definition zero : t := {|
  Name' := zero_val _;
  VolumeSource' := VolumeSourceV.zero;
|}.
Lemma deepown_zero dq : ⊢ deepown (zero_val api_core_v1.Volume.t) zero dq.
Proof.
  rewrite /deepown /zero /=.
  iSplitL.
  { done. }
  iApply VolumeSourceV.deepown_zero.
Qed.

Lemma deepown_persist c v dq :
  deepown c v dq ⊢ |==> deepown c v DfracDiscarded.
Proof.
  rewrite /deepown. iNamed 1.
