  "Hdeepown_resources" ∷ ResourceRequirementsV.deepown c.(api_core_v1.Container.Resources') v.(Resources') dq ∗
  "Hdeepown_resizepolicy" ∷ (deepown_slice ContainerResizePolicyV.deepown) c.(api_core_v1.Container.ResizePolicy') v.(ResizePolicy') dq ∗
