  "Hdeepown_lifecycle" ∷ (deepown_ptr LifecycleV.deepown) c.(api_core_v1.Container.Lifecycle') v.(Lifecycle') dq ∗
  "%Hdeepown_terminationmessagepath" ∷ (λ c v (_ : dfrac), ⌜ c = v ⌝)%I c.(api_core_v1.Container.TerminationMessagePath') v.(TerminationMessagePath') dq ∗
  "%Hdeepown_terminationmessagepolicy" ∷ (λ c v (_ : dfrac), ⌜ c = v ⌝)%I c.(api_core_v1.Container.TerminationMessagePolicy') v.(TerminationMessagePolicy') dq ∗
  "%Hdeepown_imagepullpolicy" ∷ (λ c v (_ : dfrac), ⌜ c = v ⌝)%I c.(api_core_v1.Container.ImagePullPolicy') v.(ImagePullPolicy') dq ∗
