Proof. done. Qed.

Definition deepown_l l v dq : iProp Σ := ∃ c, l ↦{dq} c ∗ deepown c v dq.

Definition zero : t := {|
  Name' := zero_val _;
  Image' := zero_val _;
  Command' := None;
  Args' := None;
  WorkingDir' := zero_val _;
  Ports' := None;
  EnvFrom' := None;
  Env' := None;
  Resources' := ResourceRequirementsV.zero;
