  TTY' := zero_val _;
|}.
Lemma deepown_zero dq : ⊢ deepown (zero_val api_core_v1.Container.t) zero dq.
Proof.
  rewrite /deepown /zero /=.
  iSplitL.
  { done. }
  iSplitL.
  { done. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { done. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply ResourceRequirementsV.deepown_zero. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { done. }
  iSplitL.
  { done. }
  iSplitL.
  { done. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { done. }
  iSplitL.
  { done. }
  done.
Qed.

Lemma deepown_persist c v dq :
  deepown c v dq ⊢ |==> deepown c v DfracDiscarded.
Proof.
  rewrite /deepown. iNamed 1.
  iAssert (|==> (deepown_slice (λ c v (_ : dfrac), ⌜ c = v ⌝)%I) c.(api_core_v1.Container.Command') v.(Command') DfracDiscarded)%I
    with "[Hdeepown_command]" as ">Hdeepown_command".
  { iApply (deepown_slice_persist with "Hdeepown_command"). intros. iIntros "H". by iModIntro. }
  iAssert (|==> (deepown_slice (λ c v (_ : dfrac), ⌜ c = v ⌝)%I) c.(api_core_v1.Container.Args') v.(Args') DfracDiscarded)%I
    with "[Hdeepown_args]" as ">Hdeepown_args".
  { iApply (deepown_slice_persist with "Hdeepown_args"). intros. iIntros "H". by iModIntro. }
  iAssert (|==> (deepown_slice ContainerPortV.deepown) c.(api_core_v1.Container.Ports') v.(Ports') DfracDiscarded)%I
    with "[Hdeepown_ports]" as ">Hdeepown_ports".
  { iApply (deepown_slice_persist with "Hdeepown_ports"). intros. apply ContainerPortV.deepown_persist. }
  iAssert (|==> (deepown_slice EnvFromSourceV.deepown) c.(api_core_v1.Container.EnvFrom') v.(EnvFrom') DfracDiscarded)%I
    with "[Hdeepown_envfrom]" as ">Hdeepown_envfrom".
  { iApply (deepown_slice_persist with "Hdeepown_envfrom"). intros. apply EnvFromSourceV.deepown_persist. }
  iAssert (|==> (deepown_slice EnvVarV.deepown) c.(api_core_v1.Container.Env') v.(Env') DfracDiscarded)%I
    with "[Hdeepown_env]" as ">Hdeepown_env".
  { iApply (deepown_slice_persist with "Hdeepown_env"). intros. apply EnvVarV.deepown_persist. }
  iAssert (|==> ResourceRequirementsV.deepown c.(api_core_v1.Container.Resources') v.(Resources') DfracDiscarded)%I
    with "[Hdeepown_resources]" as ">Hdeepown_resources".
  { iApply (ResourceRequirementsV.deepown_persist with "Hdeepown_resources"). }
  iAssert (|==> (deepown_slice ContainerResizePolicyV.deepown) c.(api_core_v1.Container.ResizePolicy') v.(ResizePolicy') DfracDiscarded)%I
    with "[Hdeepown_resizepolicy]" as ">Hdeepown_resizepolicy".
  { iApply (deepown_slice_persist with "Hdeepown_resizepolicy"). intros. apply ContainerResizePolicyV.deepown_persist. }
  iAssert (|==> (deepown_ptr (λ c v (_ : dfrac), ⌜ c = v ⌝)%I) c.(api_core_v1.Container.RestartPolicy') v.(RestartPolicy') DfracDiscarded)%I
    with "[Hdeepown_restartpolicy]" as ">Hdeepown_restartpolicy".
  { iApply (deepown_ptr_persist with "Hdeepown_restartpolicy"). intros. iIntros "H". by iModIntro. }
  iAssert (|==> (deepown_slice ContainerRestartRuleV.deepown) c.(api_core_v1.Container.RestartPolicyRules') v.(RestartPolicyRules') DfracDiscarded)%I
    with "[Hdeepown_restartpolicyrules]" as ">Hdeepown_restartpolicyrules".
  { iApply (deepown_slice_persist with "Hdeepown_restartpolicyrules"). intros. apply ContainerRestartRuleV.deepown_persist. }
  iAssert (|==> (deepown_slice VolumeMountV.deepown) c.(api_core_v1.Container.VolumeMounts') v.(VolumeMounts') DfracDiscarded)%I
    with "[Hdeepown_volumemounts]" as ">Hdeepown_volumemounts".
  { iApply (deepown_slice_persist with "Hdeepown_volumemounts"). intros. apply VolumeMountV.deepown_persist. }
  iAssert (|==> (deepown_slice VolumeDeviceV.deepown) c.(api_core_v1.Container.VolumeDevices') v.(VolumeDevices') DfracDiscarded)%I
    with "[Hdeepown_volumedevices]" as ">Hdeepown_volumedevices".
  { iApply (deepown_slice_persist with "Hdeepown_volumedevices"). intros. apply VolumeDeviceV.deepown_persist. }
  iAssert (|==> (deepown_ptr ProbeV.deepown) c.(api_core_v1.Container.LivenessProbe') v.(LivenessProbe') DfracDiscarded)%I
    with "[Hdeepown_livenessprobe]" as ">Hdeepown_livenessprobe".
  { iApply (deepown_ptr_persist with "Hdeepown_livenessprobe"). intros. apply ProbeV.deepown_persist. }
  iAssert (|==> (deepown_ptr ProbeV.deepown) c.(api_core_v1.Container.ReadinessProbe') v.(ReadinessProbe') DfracDiscarded)%I
    with "[Hdeepown_readinessprobe]" as ">Hdeepown_readinessprobe".
  { iApply (deepown_ptr_persist with "Hdeepown_readinessprobe"). intros. apply ProbeV.deepown_persist. }
  iAssert (|==> (deepown_ptr ProbeV.deepown) c.(api_core_v1.Container.StartupProbe') v.(StartupProbe') DfracDiscarded)%I
    with "[Hdeepown_startupprobe]" as ">Hdeepown_startupprobe".
  { iApply (deepown_ptr_persist with "Hdeepown_startupprobe"). intros. apply ProbeV.deepown_persist. }
  iAssert (|==> (deepown_ptr LifecycleV.deepown) c.(api_core_v1.Container.Lifecycle') v.(Lifecycle') DfracDiscarded)%I
    with "[Hdeepown_lifecycle]" as ">Hdeepown_lifecycle".
  { iApply (deepown_ptr_persist with "Hdeepown_lifecycle"). intros. apply LifecycleV.deepown_persist. }
  iAssert (|==> (deepown_ptr SecurityContextV.deepown) c.(api_core_v1.Container.SecurityContext') v.(SecurityContext') DfracDiscarded)%I
    with "[Hdeepown_securitycontext]" as ">Hdeepown_securitycontext".
  { iApply (deepown_ptr_persist with "Hdeepown_securitycontext"). intros. apply SecurityContextV.deepown_persist. }
  iModIntro. iFrame "# ∗ %".
Qed.

