Definition deepown_l l v dq : iProp Σ := ∃ c, l ↦{dq} c ∗ deepown c v dq.

Definition zero : t := {|
  Volumes' := None;
  InitContainers' := None;
  Containers' := None;
  EphemeralContainers' := None;
  RestartPolicy' := zero_val _;
  TerminationGracePeriodSeconds' := None;
  ActiveDeadlineSeconds' := None;
  DNSPolicy' := zero_val _;
  NodeSelector' := None;
  ServiceAccountName' := zero_val _;
  DeprecatedServiceAccount' := zero_val _;
  AutomountServiceAccountToken' := None;
  NodeName' := zero_val _;
  HostNetwork' := zero_val _;
  HostPID' := zero_val _;
  HostIPC' := zero_val _;
  ShareProcessNamespace' := None;
  SecurityContext' := None;
  ImagePullSecrets' := None;
  Hostname' := zero_val _;
  Subdomain' := zero_val _;
  Affinity' := None;
  SchedulerName' := zero_val _;
  Tolerations' := None;
  HostAliases' := None;
  PriorityClassName' := zero_val _;
  Priority' := None;
  DNSConfig' := None;
  ReadinessGates' := None;
  RuntimeClassName' := None;
  EnableServiceLinks' := None;
  PreemptionPolicy' := None;
  Overhead' := None;
  TopologySpreadConstraints' := None;
  SetHostnameAsFQDN' := None;
  OS' := None;
  HostUsers' := None;
  SchedulingGates' := None;
  ResourceClaims' := None;
  Resources' := None;
  HostnameOverride' := None;
|}.
Lemma deepown_zero dq : ⊢ deepown (zero_val api_core_v1.PodSpec.t) zero dq.
Proof.
  rewrite /deepown /zero /=.
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { done. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { done. }
  iSplitL.
  { iApply deepown_map_nil. }
  iSplitL.
  { done. }
  iSplitL.
  { done. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { done. }
  iSplitL.
  { done. }
  iSplitL.
  { done. }
  iSplitL.
  { done. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { done. }
  iSplitL.
  { done. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { done. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { done. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_map_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_slice_nil. }
  iSplitL.
  { iApply deepown_ptr_nil. }
  iApply deepown_ptr_nil.
Qed.

Lemma deepown_persist c v dq :
  deepown c v dq ⊢ |==> deepown c v DfracDiscarded.
Proof.
  rewrite /deepown. iNamed 1.
  iAssert (|==> (deepown_slice VolumeV.deepown) c.(api_core_v1.PodSpec.Volumes') v.(Volumes') DfracDiscarded)%I
    with "[Hdeepown_volumes]" as ">Hdeepown_volumes".
  { iApply (deepown_slice_persist with "Hdeepown_volumes"). intros. apply VolumeV.deepown_persist. }
  iAssert (|==> (deepown_slice ContainerV.deepown) c.(api_core_v1.PodSpec.InitContainers') v.(InitContainers') DfracDiscarded)%I
    with "[Hdeepown_initcontainers]" as ">Hdeepown_initcontainers".
  { iApply (deepown_slice_persist with "Hdeepown_initcontainers"). intros. apply ContainerV.deepown_persist. }
  iAssert (|==> (deepown_slice ContainerV.deepown) c.(api_core_v1.PodSpec.Containers') v.(Containers') DfracDiscarded)%I
    with "[Hdeepown_containers]" as ">Hdeepown_containers".
  { iApply (deepown_slice_persist with "Hdeepown_containers"). intros. apply ContainerV.deepown_persist. }
  iAssert (|==> (deepown_slice EphemeralContainerV.deepown) c.(api_core_v1.PodSpec.EphemeralContainers') v.(EphemeralContainers') DfracDiscarded)%I
    with "[Hdeepown_ephemeralcontainers]" as ">Hdeepown_ephemeralcontainers".
  { iApply (deepown_slice_persist with "Hdeepown_ephemeralcontainers"). intros. apply EphemeralContainerV.deepown_persist. }
  iAssert (|==> (deepown_ptr (λ c v (_ : dfrac), ⌜ c = v ⌝)%I) c.(api_core_v1.PodSpec.TerminationGracePeriodSeconds') v.(TerminationGracePeriodSeconds') DfracDiscarded)%I
    with "[Hdeepown_terminationgraceperiodseconds]" as ">Hdeepown_terminationgraceperiodseconds".
  { iApply (deepown_ptr_persist with "Hdeepown_terminationgraceperiodseconds"). intros. iIntros "H". by iModIntro. }
  iAssert (|==> (deepown_ptr (λ c v (_ : dfrac), ⌜ c = v ⌝)%I) c.(api_core_v1.PodSpec.ActiveDeadlineSeconds') v.(ActiveDeadlineSeconds') DfracDiscarded)%I
    with "[Hdeepown_activedeadlineseconds]" as ">Hdeepown_activedeadlineseconds".
  { iApply (deepown_ptr_persist with "Hdeepown_activedeadlineseconds"). intros. iIntros "H". by iModIntro. }
  iAssert (|==> (deepown_map (λ c v (_ : dfrac), ⌜ c = v ⌝)%I) c.(api_core_v1.PodSpec.NodeSelector') v.(NodeSelector') DfracDiscarded)%I
    with "[Hdeepown_nodeselector]" as ">Hdeepown_nodeselector".
  { iApply (deepown_map_persist with "Hdeepown_nodeselector"). intros. iIntros "H". by iModIntro. }
  iAssert (|==> (deepown_ptr (λ c v (_ : dfrac), ⌜ c = v ⌝)%I) c.(api_core_v1.PodSpec.AutomountServiceAccountToken') v.(AutomountServiceAccountToken') DfracDiscarded)%I
    with "[Hdeepown_automountserviceaccounttoken]" as ">Hdeepown_automountserviceaccounttoken".
  { iApply (deepown_ptr_persist with "Hdeepown_automountserviceaccounttoken"). intros. iIntros "H". by iModIntro. }
  iAssert (|==> (deepown_ptr (λ c v (_ : dfrac), ⌜ c = v ⌝)%I) c.(api_core_v1.PodSpec.ShareProcessNamespace') v.(ShareProcessNamespace') DfracDiscarded)%I
    with "[Hdeepown_shareprocessnamespace]" as ">Hdeepown_shareprocessnamespace".
  { iApply (deepown_ptr_persist with "Hdeepown_shareprocessnamespace"). intros. iIntros "H". by iModIntro. }
  iAssert (|==> (deepown_ptr PodSecurityContextV.deepown) c.(api_core_v1.PodSpec.SecurityContext') v.(SecurityContext') DfracDiscarded)%I
    with "[Hdeepown_securitycontext]" as ">Hdeepown_securitycontext".
  { iApply (deepown_ptr_persist with "Hdeepown_securitycontext"). intros. apply PodSecurityContextV.deepown_persist. }
  iAssert (|==> (deepown_slice LocalObjectReferenceV.deepown) c.(api_core_v1.PodSpec.ImagePullSecrets') v.(ImagePullSecrets') DfracDiscarded)%I
    with "[Hdeepown_imagepullsecrets]" as ">Hdeepown_imagepullsecrets".
  { iApply (deepown_slice_persist with "Hdeepown_imagepullsecrets"). intros. apply LocalObjectReferenceV.deepown_persist. }
  iAssert (|==> (deepown_ptr AffinityV.deepown) c.(api_core_v1.PodSpec.Affinity') v.(Affinity') DfracDiscarded)%I
    with "[Hdeepown_affinity]" as ">Hdeepown_affinity".
  { iApply (deepown_ptr_persist with "Hdeepown_affinity"). intros. apply AffinityV.deepown_persist. }
  iAssert (|==> (deepown_slice TolerationV.deepown) c.(api_core_v1.PodSpec.Tolerations') v.(Tolerations') DfracDiscarded)%I
    with "[Hdeepown_tolerations]" as ">Hdeepown_tolerations".
  { iApply (deepown_slice_persist with "Hdeepown_tolerations"). intros. apply TolerationV.deepown_persist. }
  iAssert (|==> (deepown_slice HostAliasV.deepown) c.(api_core_v1.PodSpec.HostAliases') v.(HostAliases') DfracDiscarded)%I
    with "[Hdeepown_hostaliases]" as ">Hdeepown_hostaliases".
  { iApply (deepown_slice_persist with "Hdeepown_hostaliases"). intros. apply HostAliasV.deepown_persist. }
  iAssert (|==> (deepown_ptr (λ c v (_ : dfrac), ⌜ c = v ⌝)%I) c.(api_core_v1.PodSpec.Priority') v.(Priority') DfracDiscarded)%I
    with "[Hdeepown_priority]" as ">Hdeepown_priority".
  { iApply (deepown_ptr_persist with "Hdeepown_priority"). intros. iIntros "H". by iModIntro. }
  iAssert (|==> (deepown_ptr PodDNSConfigV.deepown) c.(api_core_v1.PodSpec.DNSConfig') v.(DNSConfig') DfracDiscarded)%I
    with "[Hdeepown_dnsconfig]" as ">Hdeepown_dnsconfig".
  { iApply (deepown_ptr_persist with "Hdeepown_dnsconfig"). intros. apply PodDNSConfigV.deepown_persist. }
  iAssert (|==> (deepown_slice PodReadinessGateV.deepown) c.(api_core_v1.PodSpec.ReadinessGates') v.(ReadinessGates') DfracDiscarded)%I
