  iAssert (|==> PodSpecV.deepown c.(api_core_v1.Pod.Spec') v.(Spec') DfracDiscarded)%I
    with "[Hdeepown_spec]" as ">Hdeepown_spec".
  { iApply (PodSpecV.deepown_persist with "Hdeepown_spec"). }
  iAssert (|==> PodStatusV.deepown c.(api_core_v1.Pod.Status') v.(Status') DfracDiscarded)%I
    with "[Hdeepown_status]" as ">Hdeepown_status".
  { iApply (PodStatusV.deepown_persist with "Hdeepown_status"). }
  iModIntro. iFrame "# ∗ %".
Qed.

#[global] Instance deepown_persistent c v : Persistent (deepown c v DfracDiscarded).
Proof. rewrite /deepown.
  apply bi.sep_persistent.
  { apply _. }
